def count_nums(arr):
    def digit_sum(n):
        n_str = str(n)
        if n_str[0] == '-':
            return int(n_str[0] + n_str[1]) + sum(int(digit) for digit in n_str[2:])
        else:
            return sum(int(digit) for digit in n_str)

    return sum(1 for num in arr if digit_sum(num) > 0)
